import logging
import os
from .files import FilesOperations
try:
    import backports.tempfile as tempfile
except ImportError:
    import tempfile

log = logging.getLogger(__name__)


class TemplatesExtractFacade(object):
    def __init__(self, extract_strategy, templates_picker):
        self.strategy = extract_strategy
        self.finder = templates_picker

    def extract(self, archive, destination):
        """ Extract templates `archive`. Templates are extracted to temporary
        directory, then moved to `destination` directory. """
        with tempfile.TemporaryDirectory() as temp_dir:
            log.info('Extracting \'{a}\' to {d}'.format(a=archive, d=temp_dir))
            if not os.path.exists(destination):
                os.makedirs(destination)
            templates_root = self.strategy.extract(archive, temp_dir)
            log.info('Extracted succesfully.')
            self._copy_files(temp_dir=temp_dir, templates_root=templates_root,
                             destination=destination)
            log.info('Copying finished.')

    def _copy_files(self, temp_dir, templates_root, destination):
            log.info('Looking for templates in {r}'.format(r=templates_root))
            templates_dir = self.finder.get_templates_path(templates_root)
            log.info('Copying templates to {d}'.format(d=destination))
            FilesOperations.copy_dir_content(templates_dir, destination)


class TemplatesExtractRCP2Facade(TemplatesExtractFacade):
    def _copy_files(self, temp_dir, templates_root, destination):
        super(TemplatesExtractRCP2Facade, self)._copy_files(
            temp_dir=temp_dir, templates_root=templates_root,
            destination=destination)
        templates_dir = self.finder.get_templates_path(templates_root)
        modules = os.path.join(templates_dir, 'modules')
        modules_dest = os.path.join(destination, 'modules')
        FilesOperations.copy_dir_content(modules, modules_dest)


class TemplatesProcessFacade(object):
    def __init__(self, templates_recognizer, file_serializer, templates_parser,
                 heat_factory):
        self.recognizer = templates_recognizer
        self.serializer = file_serializer
        self.parser = templates_parser
        self.heat_factory = heat_factory

    def process(self, root_dir, destination):
        """ Takes all template files from `root_dir`, and matches yaml and env
        files based on their filenames. For every env-yaml pair, it takes yaml
        file to determine which variables are relevant for this configuration,
        so it allows to drop unrelevant env variables. New env files are saved
        in `destination` directory.
        """
        templates_source = self.recognizer.get_templates_paths(root_dir)
        templates = FilesOperations.copy_files(templates_source, destination)
        self.copy_template_files(templates)

    def copy_template_files(self, templates):
        yamls = self.recognizer.definition_files(templates)
        envs = self.recognizer.variable_files(templates)
        for y in yamls:
            env_path = self.recognizer.match_variables(y, envs)
            if env_path is not None:
                heat_template = self.heat_factory.create(y, env_path)
                parsed_env = self.parser.parse(heat_template)
                self.serializer.save(env_path, parsed_env)
